#include <cstdint>
#include "address.h"
#include "modules.h"
#include <vector>     // For std::vector
#include <algorithm>  // For std::find_if, std::min, std::max

// Define constants for the prefetcher
const int MAX_STREAMS = 8;
const int CONFIDENCE_THRESHOLD = 4; // Issue prefetches if confidence >= this
const int MAX_CONFIDENCE = 10;
const int INITIAL_CONFIDENCE = 0;
const champsim::block_number::difference_type AGGRESSIVE_OFFSET = 8; // Prefetch 8 blocks ahead of the current access

struct gen_aggressive_offset_s1 : public champsim::modules::prefetcher {
  using prefetcher::prefetcher;

  // Structure to hold information about an active stream/region
  struct StreamEntry {
    champsim::address ip;                  // Instruction Pointer associated with the stream
    champsim::block_number last_accessed_block; // Last block accessed by this IP
    int confidence;                        // Confidence counter for this stream

    // Default constructor for std::vector operations like replacement
    StreamEntry() : ip(champsim::address{0}), last_accessed_block(champsim::block_number{0}), confidence(INITIAL_CONFIDENCE) {}

    // Parameterized constructor
    StreamEntry(champsim::address init_ip, champsim::block_number init_blk, int init_conf)
        : ip(init_ip), last_accessed_block(init_blk), confidence(init_conf) {}
  };

  std::vector<StreamEntry> streams; // Stores active stream entries

  // Called on every core-cache access
  uint32_t prefetcher_cache_operate(champsim::address addr, champsim::address ip,
                                     uint8_t cache_hit, bool useful_prefetch,
                                     access_type type, uint32_t metadata_in) {
    champsim::block_number current_blk{addr}; // Convert address to block number for arithmetic

    // Try to find an existing stream for this IP
    auto it = std::find_if(streams.begin(), streams.end(), [&](const StreamEntry& s){ return s.ip == ip; });

    if (it != streams.end()) {
      // Stream found, update its state
      StreamEntry& s = *it;

      // Update confidence based on cache access outcome
      if (useful_prefetch) {
        // A prefetch was useful (hit on a prefetched block), positive signal for the prefetcher
        s.confidence = std::min(MAX_CONFIDENCE, s.confidence + 1);
      } else if (!cache_hit) {
        // A core access resulted in a miss, negative signal (our prefetcher might have failed)
        s.confidence = std::max(-MAX_CONFIDENCE, s.confidence - 1);
      }
      // If cache_hit is true but useful_prefetch is false, it was a hit on non-prefetched data, which is neutral for our prefetcher's confidence.

      // Update the last accessed block for this stream
      s.last_accessed_block = current_blk;

      // If confidence is high enough, issue an aggressive prefetch
      if (s.confidence >= CONFIDENCE_THRESHOLD) {
        champsim::block_number prefetch_blk = current_blk + AGGRESSIVE_OFFSET;
        // Issue the prefetch to the next level (or current level, if fill_this_level is true)
        // metadata_in is passed from the original core access
        prefetch_line(champsim::address{prefetch_blk}, true, metadata_in);
      }

      // Move this stream to the back of the vector to implement a simple LRU policy
      if (it != streams.end() - 1) { // If not already the last element
        StreamEntry moved_stream = std::move(*it); // Move content to a temporary
        streams.erase(it);                          // Remove from old position
        streams.push_back(std::move(moved_stream)); // Add to back
      }

    } else {
      // New IP encountered, create a new stream entry
      if (streams.size() < MAX_STREAMS) {
        // If there's space, add a new stream
        streams.emplace_back(ip, current_blk, INITIAL_CONFIDENCE);
      } else {
        // Streams vector is full. Evict the least recently used (front) stream
        // and replace it with the new one. Then move the new stream to the back.
        streams.front() = StreamEntry(ip, current_blk, INITIAL_CONFIDENCE);
        StreamEntry moved_stream = std::move(streams.front());
        streams.erase(streams.begin());
        streams.push_back(std::move(moved_stream));
      }

      // For any new or replaced stream, issue an initial aggressive prefetch speculatively
      champsim::block_number prefetch_blk = current_blk + AGGRESSIVE_OFFSET;
      prefetch_line(champsim::address{prefetch_blk}, true, metadata_in);
    }

    return metadata_in;
  }

  // Called on a fill into the cache being modelled
  uint32_t prefetcher_cache_fill(champsim::address addr, long set, long way,
                                  uint8_t prefetch, champsim::address evicted_addr,
                                  uint32_t metadata_in) {
    // This prefetcher primarily uses the `useful_prefetch` signal from
    // `prefetcher_cache_operate` for confidence tracking.
    // No specific logic is implemented here for confidence updates.
    return metadata_in;
  }
};

