#include <cstdint>
#include <vector>
#include <algorithm> // For std::find_if, std::rotate
#include <cstddef>   // For std::size_t
#include "address.h"
#include "modules.h"

// Constants for prefetcher behavior
constexpr int PREFETCH_DISTANCE = 4;        // How many lines ahead to prefetch from the current block
constexpr int NUM_PREFETCH_LINES = 2;       // How many consecutive lines to prefetch
constexpr int MIN_CONFIDENCE = 2;           // Minimum confidence to allow prefetches
constexpr int MAX_CONFIDENCE = 7;           // Maximum confidence value for a region
constexpr int CONFIDENCE_INCREMENT = 1;     // Amount to increase confidence upon useful prefetch
constexpr int CONFIDENCE_DECREMENT = 1;     // Amount to decrease confidence upon useless prefetch
constexpr std::size_t CONF_TABLE_SIZE = 16; // Max entries in the confidence table (LRU)
constexpr std::size_t SOURCE_ID_MAP_SIZE = 32; // Max entries in the source ID map (for metadata, LRU)

struct gen_aggressive_offset_s3 : public champsim::modules::prefetcher {
    using prefetcher::prefetcher;

    // Struct to store confidence for a specific base block
    struct RegionConfidence {
        champsim::block_number base_block;
        int confidence;
    };

    // Struct to map a source block to a unique ID, used for passing metadata
    struct SourceIDMapEntry {
        champsim::block_number source_block;
        uint32_t metadata_id;
    };

    std::vector<RegionConfidence> confidence_table;
    std::vector<SourceIDMapEntry> source_id_map;
    uint32_t next_metadata_id = 1; // 0 is reserved for 'invalid' or 'no metadata'

    // Helper to find, update confidence, or add a new entry for a block.
    // Uses LRU eviction by moving accessed/new entries to the front.
    void update_confidence(champsim::block_number block, int delta) {
        auto it = std::find_if(confidence_table.begin(), confidence_table.end(),
                               [&](const auto& entry) { return entry.base_block == block; });

        if (it != confidence_table.end()) {
            it->confidence += delta;
            if (it->confidence < 0) it->confidence = 0; // Confidence cannot go below zero
            if (it->confidence > MAX_CONFIDENCE) it->confidence = MAX_CONFIDENCE; // Cap confidence

            // Move this entry to the front (most recently used)
            std::rotate(confidence_table.begin(), it, it + 1);
        } else {
            // Add new entry only if table is not full, or if we are forced to add (e.g. positive delta)
            if (confidence_table.size() == CONF_TABLE_SIZE) {
                confidence_table.pop_back(); // Evict the least recently used entry (at the back)
            }
            // Initial confidence for a new entry (after applying delta)
            int initial_conf = std::max(0, delta);
            initial_conf = std::min(initial_conf, MAX_CONFIDENCE);
            confidence_table.insert(confidence_table.begin(), {block, initial_conf});
        }
    }

    // Helper to get or assign a unique metadata ID for a source block.
    // Uses LRU eviction for the map.
    uint32_t get_source_metadata_id(champsim::block_number source_block) {
        auto it = std::find_if(source_id_map.begin(), source_id_map.end(),
                               [&](const auto& entry) { return entry.source_block == source_block; });

        if (it != source_id_map.end()) {
            // Move this entry to the front (most recently used)
            std::rotate(source_id_map.begin(), it, it + 1);
            return it->metadata_id;
        } else {
            // Assign a new ID and add a new entry
            if (source_id_map.size() == SOURCE_ID_MAP_SIZE) {
                source_id_map.pop_back(); // Evict the least recently used entry (at the back)
            }
            uint32_t new_id = next_metadata_id++;
            if (next_metadata_id == 0) next_metadata_id = 1; // Ensure 0 is not used as a valid ID
            source_id_map.insert(source_id_map.begin(), {source_block, new_id});
            return new_id;
        }
    }

    // Helper to retrieve the source block from a given metadata ID.
    // Uses LRU for the map. Returns champsim::block_number{0} if not found or invalid ID.
    champsim::block_number get_source_block_from_metadata_id(uint32_t metadata_id) {
        if (metadata_id == 0) { // 0 is reserved for invalid/no metadata
            return champsim::block_number{0};
        }
        auto it = std::find_if(source_id_map.begin(), source_id_map.end(),
                               [&](const auto& entry) { return entry.metadata_id == metadata_id; });
        if (it != source_id_map.end()) {
            // Move this entry to the front (most recently used)
            std::rotate(source_id_map.begin(), it, it + 1);
            return it->source_block;
        }
        return champsim::block_number{0}; // Metadata ID not found
    }

    uint32_t prefetcher_cache_operate(champsim::address addr, champsim::address ip,
                                       uint8_t cache_hit, bool useful_prefetch,
                                       access_type type, uint32_t metadata_in) {
        champsim::block_number current_blk{addr};

        // Step 1: Update confidence based on prefetch usefulness
        // `metadata_in` here is the `prefetch_metadata` that was passed to `prefetch_line`
        // when `addr` was prefetched. It identifies the `current_blk`'s source.
        champsim::block_number source_blk = get_source_block_from_metadata_id(metadata_in);

        if (useful_prefetch) {
            // If the accessed address `addr` was a useful prefetch,
            // increase the confidence of its original source block.
            if (source_blk != champsim::block_number{0}) {
                update_confidence(source_blk, CONFIDENCE_INCREMENT);
            }
        } else if (metadata_in != 0) {
            // If `addr` was a prefetch (indicated by non-zero metadata_in)
            // but was NOT useful, decrease confidence of its source.
            if (source_blk != champsim::block_number{0}) {
                update_confidence(source_blk, -CONFIDENCE_DECREMENT);
            }
        }

        // Step 2: Decide whether to issue new prefetches
        int current_confidence = 0;
        auto it_conf = std::find_if(confidence_table.begin(), confidence_table.end(),
                                    [&](const auto& entry) { return entry.base_block == current_blk; });
        if (it_conf != confidence_table.end()) {
            current_confidence = it_conf->confidence;
            // Move to front (LRU)
            std::rotate(confidence_table.begin(), it_conf, it_conf + 1);
        }

        // Issue prefetches only if confidence for the current block's region is high enough.
        // If the block is not in the confidence table, assume neutral confidence allowing prefetch.
        if (current_confidence >= MIN_CONFIDENCE || it_conf == confidence_table.end()) {
            // Get a metadata ID for the current access, which will be passed to
            // future `prefetcher_cache_operate` calls if these prefetches are accessed.
            uint32_t pf_source_metadata_id = get_source_metadata_id(current_blk);

            for (int i = 0; i < NUM_PREFETCH_LINES; ++i) {
                champsim::block_number pf_blk = current_blk + PREFETCH_DISTANCE + i;
                // Issue the prefetch: true for fill_this_level, and pass our source metadata ID.
                prefetch_line(champsim::address{pf_blk}, true, pf_source_metadata_id);
            }
        }

        // This method returns metadata that the prefetcher itself associates with *this* access.
        // It's not the `prefetch_metadata` passed to `prefetch_line`. We don't use it, so return 0.
        return 0;
    }

    uint32_t prefetcher_cache_fill(champsim::address addr, long set, long way,
                                    uint8_t prefetch, champsim::address evicted_addr,
                                    uint32_t metadata_in) {
        // This prefetcher uses `useful_prefetch` in `prefetcher_cache_operate`
        // for its logic, and does not need to react to cache fill events directly.
        return 0; // No metadata returned
    }
};
